"use strict";
// Every string-keyed read and every write of a tracked object is recorded,
// so a program can show how often a member was read and whether it was
// written at all.
const log = [];
function tracked(store) {
  return new Proxy(store, {
    get(target, key) {
      if (typeof key === "string") log.push("get " + key);
      return target[key];
    },
    set(target, key, value) {
      log.push("set " + String(key));
      target[key] = value;
      return true;
    },
  });
}
class Scoreboard {
  constructor() {
    this.round = 0;
    this.limit = 3;
    this.title = undefined;
    this.host = "ada";
    this.note = null;
    this.open = false;
    this.bonus = undefined;
    this.players = undefined;
  }
}
let current = null;
exports.Scoreboard = Scoreboard;
exports.open = () => (current = tracked(new Scoreboard()));
exports.current = () => (log.push("current"), current);
exports.counters = () => (current = tracked({ wins: 2, losses: 0 }));
exports.trace = () => log.splice(0).join(",");
exports.snapshot = () => JSON.stringify(current);
